 EditorSceneManager.SaveScene(scene);var backup="Library/PanopticonBackup/ROOM2_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";Directory.CreateDirectory(Path.GetDirectoryName(backup));File.Copy(scene.path,backup);
 foreach(var f in new[]{"Textures","Materials","Meshes"}){if(!AssetDatabase.IsValidFolder(Root+"/"+f))AssetDatabase.CreateFolder(Root,f);}
 string[] photos={"codex-clipboard-aaaec47f-51c6-4b04-84aa-c7883e56c97c.png","codex-clipboard-cf79294d-adae-4825-8c0f-5f51676f81b0.png","codex-clipboard-850f10a0-e57a-46d0-adc1-c3bf9a74db73.png"};
 for(int i=0;i<3;i++){File.Copy("C:/Users/一只小段/AppData/Local/Temp/"+photos[i],Root+"/Textures/Memory_"+i+".png",true);AssetDatabase.ImportAsset(Root+"/Textures/Memory_"+i+".png");var importer=(TextureImporter)AssetImporter.GetAtPath(Root+"/Textures/Memory_"+i+".png");importer.isReadable=true;importer.npotScale=TextureImporterNPOTScale.None;importer.maxTextureSize=2048;importer.mipmapEnabled=true;importer.wrapMode=TextureWrapMode.Clamp;importer.SaveAndReimport();}
 var root=new GameObject("ROOM2 - Green memory capture");var hall=root.AddComponent<PanopticonHall>();hall.scanner=UnityEngine.Object.FindFirstObjectByType<SpatialScanEvent>();var scan=hall.scanner;scan.startDelay=1.8f;scan.scanDistance=56;scan.scanDuration=22;scan.repeatDelay=5;scan.repeatScans=true;scan.screenShockEnabled=false;scan.scanTrailLength=16.36f;scan.scanBandWidth=.8f;scan.scanBloomIntensity=.48f;
 hall.memories=new PanopticonHall.Memory[3];Vector3[] positions={new Vector3(-13.3f,38.65f,-150.2f),new Vector3(1.8f,38.65f,-140.4f),new Vector3(-5.5f,38.75f,-128.8f)};Vector3[] normal={Vector3.right,Vector3.left,Vector3.back};float[] widths={3.1f,4.5f,3.65f};string[] labels={"DIAL PAINTING / LABOR MEMORY","FACTORY / COLLECTIVE MEMORY","LIP-POINTING / RECONSTRUCTED SCENE"};
 var template=AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/Holograms（全息投影）/Materials/Examples/Basic/Scanline_Hologram_Empty.mat");
 for(int i=0;i<3;i++){var anchor=new GameObject("Echo "+(i+1)+" - "+labels[i]);anchor.transform.SetParent(root.transform);anchor.transform.SetPositionAndRotation(positions[i],Quaternion.LookRotation(-normal[i]));var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Textures/Memory_"+i+".png");
 var mat=new Material(template){name="Memory "+i+" - imported hologram scanlines"};mat.SetTexture("_Hologram_Texture",tex);mat.SetColor("_Hologram_Color",new Color(.025f,.35f,.12f,.035f));mat.SetColor("_Texture_Tint_Color",new Color(.15f,.72f,.42f,.80f));mat.SetFloat("_Emission_Scale",1.1f);mat.SetFloat("_Pattern_Density",75);mat.SetFloat("_Pattern_Speed",.6f);mat.SetFloat("_Pattern_Boost",.12f);mat.SetFloat("_Displacement_Offset",.003f);mat.SetFloat("_Displacement_Density",.1f);mat.SetFloat("_Displacement_Speed",.12f);AssetDatabase.CreateAsset(mat,Root+"/Materials/Memory_"+i+".mat");
 var surface=new GameObject("Original photo - relief hologram",typeof(MeshFilter),typeof(MeshRenderer));surface.transform.SetParent(anchor.transform,false);surface.GetComponent<MeshFilter>().sharedMesh=PhotoMesh(tex,widths[i],i);var render=surface.GetComponent<MeshRenderer>();render.sharedMaterial=mat;render.shadowCastingMode=ShadowCastingMode.Off;render.receiveShadows=false;
 var projection=new GameObject("Projection rays and dust");projection.transform.SetParent(anchor.transform,false);var ps=projection.AddComponent<ParticleSystem>();var main=ps.main;main.startColor=new Color(.10f,.85f,.35f,.4f);main.startSize=.018f;main.startLifetime=2;main.startSpeed=.18f;main.maxParticles=100;main.simulationSpace=ParticleSystemSimulationSpace.Local;var emission=ps.emission;emission.rateOverTime=15;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(widths[i],2,.05f);var dust=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));dust.SetColor("_BaseColor",new Color(.08f,1,.3f,.45f));AssetDatabase.CreateAsset(dust,Root+"/Materials/ProjectionDust_"+i+".mat");ps.GetComponent<ParticleSystemRenderer>().sharedMaterial=dust;
 hall.memories[i]=new PanopticonHall.Memory{label=labels[i],anchor=anchor.transform,surfaces=new Renderer[]{render},projection=projection};
 }
 var dissolveShader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/小资产们/溶解特效/URP/ShaderGraph/DoubleSide/Dissolve_Unlit_DoubleSide.shadergraph");var dissolve=new Material(dissolveShader){name="Panopticon - imported dissolve grid"};dissolve.SetColor("_BaseColor",new Color(.015f,.24f,.055f));dissolve.SetColor("_EdgeColor",new Color(.18f,1,.44f));dissolve.SetFloat("_EdgeColorIntensity",2.8f);dissolve.SetFloat("_EdgeWidth",.07f);dissolve.SetFloat("_NoiseScale",9);dissolve.SetFloat("_Dissolve",.1f);AssetDatabase.CreateAsset(dissolve,Root+"/Materials/ScanLattice_Dissolve.mat");hall.dissolveMaterial=dissolve;
 var lattice=new GameObject("Moving radar lattice - imported dissolve",typeof(MeshFilter),typeof(MeshRenderer));lattice.transform.SetParent(root.transform);lattice.transform.position=new Vector3(-5.6f,42,-160);lattice.GetComponent<MeshFilter>().sharedMesh=Lattice();lattice.GetComponent<MeshRenderer>().sharedMaterial=dissolve;lattice.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;hall.grid=lattice.transform;
