 for(int i=0;i<2;i++){var door=GameObject.CreatePrimitive(PrimitiveType.Cube);door.name=i==0?"Archive shutter left":"Archive shutter right";door.transform.SetParent(gateway.transform,true);door.transform.position=new Vector3(-5.5f+(i==0?-.72f:.72f),38.91f,-117.22f);door.transform.localScale=new Vector3(1.43f,3.95f,.18f);door.GetComponent<Renderer>().sharedMaterial=iron;UnityEngine.Object.DestroyImmediate(door.GetComponent<Collider>());if(i==0)hall.doorLeft=door.transform;else hall.doorRight=door.transform;}
 var block=new GameObject("Archive locked gate collider",typeof(BoxCollider));block.transform.SetParent(gateway.transform);block.transform.position=new Vector3(-5.5f,38.9f,-117.4f);block.GetComponent<BoxCollider>().size=new Vector3(2.9f,3.9f,.25f);hall.gateBlock=block.GetComponent<Collider>();
 hall.hallLights=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(l=>l.transform.position.z>-165&&l.transform.position.z<-115).ToArray();hall.sound=root.AddComponent<AudioSource>();hall.sound.playOnAwake=false;hall.sound.spatialBlend=0;var hud=Resources.Load<GameObject>("SurveyInterface").GetComponent<SurveyHUD>();hall.shutter=hud.click;hall.fracture=hud.reveal;
 var old=GameObject.Find("Redacted medical folio");if(old!=null){var reveal=old.GetComponent<SurveyScanReveal>();if(reveal!=null)reveal.enabled=false;var node=old.GetComponent<SurveyNode>();if(node!=null)node.enabled=false;var inspect=old.GetComponent<NarrativeInspectable>();if(inspect!=null)inspect.enabled=false;foreach(var r in old.GetComponentsInChildren<Renderer>())r.enabled=false;}
 EditorUtility.SetDirty(scan);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Selection.activeGameObject=root;return "Installed three 5-second photo holograms, imported dissolution lattice and archive shutters. Backup: "+backup;
 }
 static Mesh PhotoMesh(Texture2D tex,float width,int which){int nx=280,ny=Mathf.RoundToInt(nx*(float)tex.height/tex.width);float height=width*tex.height/tex.width;var verts=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();
 for(int y=0;y<=ny;y++)for(int x=0;x<=nx;x++){float u=x/(float)nx,v=y/(float)ny;float l=tex.GetPixelBilinear(u,v).grayscale;verts.Add(new Vector3((u-.5f)*width,(v-.5f)*height,-l*.10f));uv.Add(new Vector2(u,v));}
 for(int y=0;y<ny;y++)for(int x=0;x<nx;x++){float u=(x+.5f)/nx,v=(y+.5f)/ny;if(!Inside(u,1-v,which))continue;int a=y*(nx+1)+x;tris.AddRange(new[]{a,a+nx+1,a+1,a+1,a+nx+1,a+nx+2});}
 var mesh=new Mesh{name="Original photo "+which+" - shallow relief",indexFormat=IndexFormat.UInt32};mesh.SetVertices(verts);mesh.SetUVs(0,uv);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Root+"/Meshes/Memory_"+which+".asset");return mesh;}
 static bool Inside(float x,float y,int which){Vector2[] polygon;
 if(which==0)polygon=new[]{new Vector2(.12f,1),new Vector2(.08f,.63f),new Vector2(.16f,.40f),new Vector2(.35f,.28f),new Vector2(.42f,.10f),new Vector2(.57f,.025f),new Vector2(.73f,.065f),new Vector2(.8f,.18f),new Vector2(.73f,.33f),new Vector2(.64f,.43f),new Vector2(.90f,.49f),new Vector2(.94f,.62f),new Vector2(.77f,.74f),new Vector2(.72f,1)};
 else if(which==2)polygon=new[]{new Vector2(.04f,.91f),new Vector2(.10f,.54f),new Vector2(.17f,.29f),new Vector2(.21f,.27f),new Vector2(.29f,.29f),new Vector2(.36f,.47f),new Vector2(.47f,.36f),new Vector2(.54f,.34f),new Vector2(.61f,.42f),new Vector2(.69f,.36f),new Vector2(.76f,.35f),new Vector2(.84f,.42f),new Vector2(.93f,.79f),new Vector2(.97f,1),new Vector2(.20f,1)};
 else {float fade=Mathf.Min(x,1-x, y,1-y);return fade>.025f||(Mathf.PerlinNoise(x*57,y*61)>.58f&&fade>.005f);}
 bool yes=false;for(int i=0,j=polygon.Length-1;i<polygon.Length;j=i++)if((polygon[i].y>y)!=(polygon[j].y>y)&&x<(polygon[j].x-polygon[i].x)*(y-polygon[i].y)/(polygon[j].y-polygon[i].y)+polygon[i].x)yes=!yes;return yes;}
 static Mesh Lattice(){var verts=new List<Vector3>();var indices=new List<int>();Action<float,float,float,float> quad=(x,y,w,h)=>{int n=verts.Count;verts.AddRange(new[]{new Vector3(x-w/2,y-h/2,0),new Vector3(x+w/2,y-h/2,0),new Vector3(x+w/2,y+h/2,0),new Vector3(x-w/2,y+h/2,0)});indices.AddRange(new[]{n,n+2,n+1,n,n+3,n+2});};for(float x=-11;x<=11;x+=.85f)quad(x,0,.018f,10);for(float y=-5;y<=5;y+=.85f)quad(0,y,22,.018f);var mesh=new Mesh{name="Open radar lattice"};mesh.SetVertices(verts);mesh.SetTriangles(indices,0);mesh.SetUVs(0,verts.Select(v=>new Vector2((v.x+11)/22,(v.y+5)/10)).ToList());mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Root+"/Meshes/ScanLattice.asset");return mesh;}
}
